#!/bin/sh
# GENERATED by scripts/ops-jobs.ts from infra/hosts/ops-jobs.json: do not edit.
# Runs one operator job in the ops image (Run 6.2, P-111, D-47):
#
#   /opt/mykey/hosts/ops-run.sh <job> -- <command> [args...]
#
# The job fixes the command, the database role and exactly the files mounted.
# The container reaches PostgreSQL and OpenBao by the names in their
# certificates, on the host network; it cannot write outside the job's
# directories. Secret values never appear here: only file names.
# MYKEY_OPS_DRY_RUN=1 prints the docker command, one word per line, and checks
# no file.
set -euf

host_env=${MYKEY_HOST_ENV:-/etc/mykey/host.env}
usage() {
	echo "usage: ops-run.sh <job> -- <command> [args...]" >&2
	exit 64
}

[ "$#" -ge 3 ] || usage
job=$1
[ "$2" = "--" ] || usage
shift 2

case "$job" in
  status-check)
    command=operations
    files="/etc/mykey/secrets/ops/maintenance"
    fixed="--env=MYKEY_DB_USER=maintenance --mount=type=bind,source=/etc/mykey/secrets/ops/maintenance,target=/run/mykey/secrets/db-password,readonly"
    ;;
  audit-archive)
    command=audit-archive
    files="/etc/mykey/secrets/ops/maintenance /etc/mykey/secrets/r2-audit-archive/account-id /etc/mykey/secrets/r2-audit-archive/access-key-id /etc/mykey/secrets/r2-audit-archive/secret-access-key"
    fixed="--env=MYKEY_DB_USER=maintenance --env=MYKEY_AUDIT_BUCKET=mykey-audit-archive --env=MYKEY_R2_DIR=/run/mykey/secrets/r2 --env=MYKEY_BAO_ROTATED_DIR=/run/mykey/bao-audit --mount=type=bind,source=/etc/mykey/secrets/ops/maintenance,target=/run/mykey/secrets/db-password,readonly --mount=type=bind,source=/etc/mykey/secrets/r2-audit-archive/account-id,target=/run/mykey/secrets/r2/account-id,readonly --mount=type=bind,source=/etc/mykey/secrets/r2-audit-archive/access-key-id,target=/run/mykey/secrets/r2/access-key-id,readonly --mount=type=bind,source=/etc/mykey/secrets/r2-audit-archive/secret-access-key,target=/run/mykey/secrets/r2/secret-access-key,readonly --mount=type=bind,source=/var/lib/mykey/bao-audit/rotated,target=/run/mykey/bao-audit"
    ;;
  capture)
    command=capture
    files="/etc/mykey/secrets/ops/maintenance"
    fixed="--env=MYKEY_DB_USER=maintenance --env=MYKEY_PAIR_SCRATCH=/run/mykey/pairs --mount=type=bind,source=/etc/mykey/secrets/ops/maintenance,target=/run/mykey/secrets/db-password,readonly --mount=type=bind,source=/var/lib/mykey/pairs,target=/run/mykey/pairs"
    ;;
  pair)
    command=pair
    files="/etc/mykey/secrets/ops/maintenance /etc/mykey/secrets/r2-pairs/account-id /etc/mykey/secrets/r2-pairs/access-key-id /etc/mykey/secrets/r2-pairs/secret-access-key /etc/mykey/secrets/backup/signing-key"
    fixed="--env=MYKEY_DB_USER=maintenance --env=MYKEY_PAIR_SCRATCH=/run/mykey/pairs --env=MYKEY_R2_DIR=/run/mykey/secrets/r2 --env=MYKEY_PAIR_SIGNER=k1 --mount=type=bind,source=/etc/mykey/secrets/ops/maintenance,target=/run/mykey/secrets/db-password,readonly --mount=type=bind,source=/etc/mykey/secrets/r2-pairs/account-id,target=/run/mykey/secrets/r2/account-id,readonly --mount=type=bind,source=/etc/mykey/secrets/r2-pairs/access-key-id,target=/run/mykey/secrets/r2/access-key-id,readonly --mount=type=bind,source=/etc/mykey/secrets/r2-pairs/secret-access-key,target=/run/mykey/secrets/r2/secret-access-key,readonly --mount=type=bind,source=/etc/mykey/secrets/backup/signing-key,target=/run/mykey/secrets/backup/signing-key,readonly --mount=type=bind,source=/var/lib/mykey/pairs,target=/run/mykey/pairs"
    ;;
  *)
    echo "ops-run.sh: unknown job $job" >&2
    exit 64
    ;;
esac

if [ "$1" != "$command" ]; then
	echo "ops-run.sh: job $job runs only ops $command" >&2
	exit 64
fi

setting() {
	sed -n "s/^$1=//p" "$host_env" | tail -n 1
}
image=$(setting OPS_IMAGE)
if [ -z "$image" ]; then
	echo "ops-run.sh: OPS_IMAGE is not set in host.env (node scripts/host.ts <host> image ops <tar>)" >&2
	exit 1
fi
host_name=$(setting MYKEY_HOST_NAME)
if [ -z "$host_name" ]; then
	echo "ops-run.sh: MYKEY_HOST_NAME is not set in host.env (node scripts/host.ts <host> ops-secrets)" >&2
	exit 1
fi

if [ -z "${MYKEY_OPS_DRY_RUN:-}" ]; then
	for file in $files; do
		if [ ! -r "$file" ]; then
			echo "ops-run.sh: $file is missing (node scripts/host.ts <host> ops-secrets)" >&2
			exit 1
		fi
	done
fi

# The fixed words hold no space and no wildcard (rendered and checked).
# shellcheck disable=SC2086
set -- docker run --rm -i --network host --read-only --cap-drop ALL \
	--security-opt no-new-privileges --user 1000:1000 --ulimit core=0 \
	--add-host postgres:10.78.2.2 --add-host openbao:10.78.3.2 \
	--tmpfs /tmp \
	--env=MYKEY_DB_HOST=postgres --env=MYKEY_DB_PORT=5432 --env=MYKEY_DB_NAME=postgres \
	--env=MYKEY_DB_PASSWORD_FILE=/run/mykey/secrets/db-password \
	--env=MYKEY_DB_CA_FILE=/run/mykey/tls/ca.crt \
	"--env=MYKEY_OPS_HOST=$host_name" \
	--mount=type=bind,source=/etc/mykey/pki/ca.crt,target=/run/mykey/tls/ca.crt,readonly \
	$fixed "$image" "$@"

if [ -n "${MYKEY_OPS_DRY_RUN:-}" ]; then
	for word in "$@"; do
		case "$word" in
		--env=* | --mount=*) printf '%s\n' "${word%%=*}" "${word#*=}" ;;
		*) printf '%s\n' "$word" ;;
		esac
	done
	exit 0
fi
exec "$@"
